"""Build an offline review file or merge exported reviews into a separate ledger copy."""
import argparse, copy, json
from pathlib import Path

CAUSES={"out","net","two_bounces","replay","ace","winner","other"}
def build(data, target):
    players=data["players"]; ids={p["id"] for p in players}
    if len(players)!=2 or len(ids)!=2: raise ValueError("Exactly two unique player IDs required")
    pids=[r["pointId"] for r in data["rows"]]
    if len(pids)!=len(set(pids)): raise ValueError("Duplicate pointId")
    if any(r.get("serverId") not in ids for r in data["rows"]): raise ValueError("Unknown server")
    if not data.get("source") or not data.get("ledgerRevision"): raise ValueError("Source and revision required")
    template=(Path(__file__).parent.parent/"examples/review-template.html").read_text(encoding="utf-8")
    payload=json.dumps(data,ensure_ascii=False).replace("&","\\u0026").replace("<","\\u003c").replace(">","\\u003e")
    if template.count("__DATA__")!=1: raise ValueError("Template placeholder missing/duplicated")
    Path(target).write_text(template.replace("__DATA__",payload),encoding="utf-8")

def merge(ledger, review):
    if review.get("schema")!="tennis-point-review/v1": raise ValueError("Unsupported schema")
    if review.get("source")!=ledger.get("source"): raise ValueError("Source mismatch")
    if review.get("ledgerRevision")!=ledger.get("ledgerRevision"): raise ValueError("Revision mismatch: reconcile before merge")
    out=copy.deepcopy(ledger); points={p["pointId"]:p for p in out["points"]}
    ids={p["id"] for p in ledger["players"]}; seen=set()
    for r in review["rows"]:
        pid=r["pointId"]
        if pid in seen or pid not in points: raise ValueError("Duplicate/unknown pointId: "+pid)
        seen.add(pid)
        if r.get("scoringPlayerId") is not None and r["scoringPlayerId"] not in ids: raise ValueError("Unknown scoring player")
        if r.get("deadBallType") is not None and r["deadBallType"] not in CAUSES: raise ValueError("Unknown dead-ball type")
        if r.get("status") not in ("pending","partial","resolved","replay","unresolved"): raise ValueError("Unknown review status")
        undetermined=r.get("winnerUndetermined") is True and r.get("reviewConfirmed") is True
        if r.get("status")=="unresolved" and not undetermined: raise ValueError("Unresolved requires an explicit human review")
        if undetermined and (r.get("status")!="unresolved" or r.get("scoringPlayerId") is not None or r.get("deadBallType") in ("ace","replay") or r.get("doubleFaultConfirmed") is True):
            raise ValueError("Undetermined winner conflicts with a determinate result")
        p=points[pid]; p.setdefault("reviewHistory",[]).append(copy.deepcopy(r))
        if r.get("status")=="pending": continue
        p["reviewStatus"]=r["status"]
        if undetermined:
            p.setdefault("winnerResolutionHistory",[]).append({k:copy.deepcopy(p.get(k)) for k in ("scoringPlayerId","winner","adoptedWinner","doubleFaultConfirmed","userReviewConfirmed","provenance")})
            if p.get("userReviewConfirmed") or p.get("doubleFaultConfirmed") is True:
                p["reviewConflict"]="New human-undetermined report conflicts with a previously confirmed result; reconcile evidence."
            p.update(scoringPlayerId=None,winner=None,adoptedWinner=None,winnerUndetermined=True,winnerResolutionSource="human_unresolved",doubleFaultConfirmed=None,statsIncluded=False,userReviewConfirmed=False,humanReviewCompleted=True)
            if p.get("deadBallType")=="ace": p["deadBallType"]=None
            if p.get("ending") in ("ACE","DF"): p["ending"]=None
        elif r.get("reviewConfirmed") is True and (r.get("scoringPlayerId") is not None or r.get("deadBallType")=="replay"):
            if r.get("scoringPlayerId") is not None:
                p.update(winner=r.get("scoringPlayerId"),adoptedWinner=r.get("scoringPlayerId"))
            p.update(winnerUndetermined=False,requiresScoreInference=False,winnerResolutionSource="human_confirmed",userReviewConfirmed=True,humanReviewCompleted=True)
        for key in ("scoringPlayerId","deadBallType","doubleFaultConfirmed"):
            if r.get(key) is not None: p[key]=r[key]
        if r.get("note"): p["reviewNote"]=r["note"]
        if r.get("deadBallType")=="replay":
            p.update(scoringPlayerId=None,countsTowardScore=False,countingStatus="replay")
        elif r.get("countsTowardScore") is False:
            p.update(countsTowardScore=False,countingStatus=r.get("countingStatus","extra"))
        # An absent/unchecked exclusion never silently restores a previously excluded point.
        if r.get("countingIssueResolved") is not None: p["userCountingIssueAnswer"]=r["countingIssueResolved"]
        if undetermined:
            p["requiresScoreInference"]=p.get("countsTowardScore") is not False
            p["inferenceRequired"]=p["requiresScoreInference"]
        elif r.get("reviewConfirmed") is True and not p.get("winnerUndetermined"):
            p["inferenceRequired"]=False
    out["requiresScoreInference"]=any(p.get("requiresScoreInference") for p in out["points"])
    out["requiresScoreAndStatsRebuild"]=True
    # Internal work queue only: keep the user-facing review form unchanged.
    out["agentRecheckPointIds"]=sorted(seen)
    out["requiresUserFieldByFieldReview"]=False
    return out

if __name__=="__main__":
    p=argparse.ArgumentParser(); sub=p.add_subparsers(dest="command",required=True)
    b=sub.add_parser("build"); b.add_argument("data"); b.add_argument("output")
    m=sub.add_parser("merge"); m.add_argument("ledger"); m.add_argument("review"); m.add_argument("output")
    a=p.parse_args()
    def read(path): return json.loads(Path(path).read_text(encoding="utf-8-sig"))
    if a.command=="build": build(read(a.data),a.output)
    else:
        if Path(a.output).resolve()==Path(a.ledger).resolve(): raise ValueError("Write a new ledger revision, not the original")
        text=Path(a.review).read_text(encoding="utf-8-sig"); review=json.loads(text[text.index("{"):])
        Path(a.output).write_text(json.dumps(merge(read(a.ledger),review),ensure_ascii=False,indent=2),encoding="utf-8")

scripts/score_audit.py.text:
"""Pure singles score audit; no media or editor writes. Input config + points, output JSON."""
import argparse, copy, json

def other(p):
    if p not in ("A", "B"):
        raise ValueError("Player IDs for this helper must be A or B")
    return "B" if p == "A" else "A"

def game_won(points, p, advantage):
    return points[p] >= 4 and (not advantage or points[p] - points[other(p)] >= 2)

def tiebreak_server(first, n):
    return first if n == 0 or ((n - 1) // 2) % 2 else other(first)

def point_display(points, advantage):
    if advantage and min(points.values()) >= 3:
        if points["A"] == points["B"]: return {"A":"40","B":"40"}, "Deuce"
        leader = max(points, key=points.get)
        return {leader:"AD", other(leader):"40"}, ""
    return {p:("0","15","30","40")[min(3,points[p])] for p in ("A","B")}, ("金球" if not advantage and points["A"] == points["B"] == 3 else "")

def audit(config, rows):
    c = copy.deepcopy(config)
    mode = c["mode"]
    if mode not in ("sets","timed","tiebreak"): raise ValueError("Unsupported mode")
    first = c["nextServer"]; other(first)
    advantage = c.get("advantage", False)
    if not isinstance(advantage, bool): raise ValueError("advantage must be boolean")
    if mode == "sets":
        if c.get("bestOf") not in (1,3,5): raise ValueError("Specify bestOf 1, 3, or 5")
        if c.get("gamesToWin") not in (4,6): raise ValueError("Specify gamesToWin 4 or 6")
        if c.get("tiebreakAt") not in (c["gamesToWin"]-1,c["gamesToWin"]): raise ValueError("Specify tiebreakAt")
    if c.get("tiebreakTarget",7) not in (7,10): raise ValueError("Specify tiebreak target 7 or 10")
    points = dict(c.get("initialPoints", {"A":0,"B":0}))
    games = dict(c.get("initialGames", {"A":0,"B":0}))
    sets = dict(c.get("initialSets", {"A":0,"B":0}))
    for pair in (points,games,sets):
        if set(pair) != {"A","B"} or any(type(v) is not int or v < 0 for v in pair.values()):
            raise ValueError("Scores must be nonnegative raw integer counts for A and B")
    tb = mode == "tiebreak" or (mode == "sets" and games["A"] == games["B"] == c["tiebreakAt"])
    if tb and sum(points.values()) and "tiebreakFirstServer" not in c:
        raise ValueError("Mid-tiebreak requires tiebreakFirstServer")
    tb_first = c.get("tiebreakFirstServer", first)
    other(tb_first)
    logs, conflicts, completed_games, completed_sets, seen = [], [], [], [], set()
    ended = False
    for row in rows:
        pid = row["pointId"]
        if pid in seen: raise ValueError("Duplicate pointId: " + pid)
        seen.add(pid)
        if row.get("countsTowardScore",True) is False or row.get("countingStatus") in ("replay","extra","practice"):
            logs.append({"pointId":pid,"excluded":True}); continue
        if ended:
            conflicts.append({"pointId":pid,"issue":"counted point after match completion"}); break
        winner = row.get("winner")
        if winner not in ("A","B"):
            conflicts.append({"pointId":pid,"issue":"unknown winner; downstream score stopped"}); break
        if not tb and any(game_won(points,p,advantage) for p in ("A","B")):
            conflicts.append({"pointId":pid,"issue":"initial game already complete"}); break
        server = tiebreak_server(tb_first,sum(points.values())) if tb else first
        display, badge = ({p:str(v) for p,v in points.items()},"TB") if tb else point_display(points,advantage)
        rec = {"pointId":pid,"server":server,"winner":winner,"before":{"points":dict(points),"display":display,"games":dict(games),"sets":dict(sets),"badge":badge},"breakPoint":False}
        if row.get("server") and row["server"] != server:
            conflicts.append({"pointId":pid,"issue":"observed server differs from score progression","expected":server,"observed":row["server"]})
        if not tb:
            probe = dict(points); probe[other(server)] += 1
            rec["breakPoint"] = game_won(probe,other(server),advantage)
        points[winner] += 1
        target = c.get("tiebreakTarget",7)
        if mode == "sets" and sum(sets.values()) == c["bestOf"]-1:
            target = c.get("finalSetTiebreakTarget", target)
        won = points[winner] >= target and points[winner]-points[other(winner)] >= 2 if tb else game_won(points,winner,advantage)
        early_award = False
        if row.get("recordedGameWinner") and not won:
            other(row["recordedGameWinner"])
            early_award = (not tb and row.get("exceptionType")=="onsite_award_before_rule_completion"
                           and row.get("exceptionConfirmed") is True
                           and bool(str(row.get("exceptionNote") or "").strip()))
            if not early_award:
                conflicts.append({"pointId":pid,"issue":"unconfirmed or unsupported game override before rule game completion"})
        if won or early_award:
            if mode == "tiebreak":
                ended = True
                rec["tiebreakWinner"] = winner
            else:
                recorded = row.get("recordedGameWinner", winner); other(recorded)
                if not early_award and recorded != winner and (row.get("exceptionConfirmed") is not True or not row.get("exceptionNote")):
                    conflicts.append({"pointId":pid,"issue":"unconfirmed game attribution exception"})
                    recorded = winner
                games[recorded] += 1
                game = {"endPointId":pid,"server":tb_first if tb else server,"rulesWinner":winner if won else None,"rulesComplete":bool(won),"recordedWinner":recorded,"tiebreak":tb,"rawPoints":dict(points)}
                if early_award or recorded != winner:
                    game.update(exceptionNote=row["exceptionNote"],exceptionConfirmed=True,
                                exceptionType="onsite_award_before_rule_completion" if early_award else "onsite_attribution_override")
                completed_games.append(game); rec["gameEnd"] = game
                first = other(tb_first if tb else server)
                set_won = mode == "sets" and (tb or (games[recorded] >= c["gamesToWin"] and games[recorded]-games[other(recorded)] >= 2))
                points = {"A":0,"B":0}
                if set_won:
                    completed_sets.append({"winner":recorded,"games":dict(games)})
                    sets[recorded] += 1; rec["setEnd"] = completed_sets[-1]
                    ended = sets[recorded] >= c["bestOf"]//2+1
                    games = {"A":0,"B":0}
                tb = mode == "sets" and games["A"] == games["B"] == c["tiebreakAt"]
                if tb: tb_first = first
        rec["after"] = {"points":dict(points),"games":dict(games),"sets":dict(sets)}
        logs.append(rec)
    return {"states":logs,"games":completed_games,"sets":completed_sets,"score":{"points":points,"games":games,"sets":sets},"matchComplete":ended,"conflicts":conflicts,"scope":"provided footage only","rulesCompleteGameCount":sum(g["rulesComplete"] for g in completed_games),"onsiteExceptions":[g for g in completed_games if g.get("exceptionType")]}

if __name__ == "__main__":
    parser=argparse.ArgumentParser(); parser.add_argument("input"); args=parser.parse_args()
    with open(args.input,encoding="utf-8-sig") as f: data=json.load(f)
    print(json.dumps(audit(data["config"],data["points"]),ensure_ascii=False,indent=2))

scripts/serve_overlay.py.text:
"""Pure timing plan for verified, retained serves; no media or editor writes."""
import argparse, json, math
from fractions import Fraction
from pathlib import Path

def fraction(value):
    return Fraction(str(value))

def build_plan(records, fps):
    """See helper-usage.md. All source timestamps are integer microseconds.

    confirmedPostContactUs is visually verified outgoing-ball evidence, NOT a
    fitted launch time. The caller supplies the current source-to-edit mapping.
    Nonlinear time remaps must be split into constant-rate spans beforehand.
    """
    fps=fraction(fps)
    if fps<=0:raise ValueError('fps must be positive')
    limit=math.floor(3*fps)
    if limit<1:raise ValueError('fps too low for a three-second interval')
    seen=set();out=[]
    for r in records:
        key=(r['setNumber'],r['serveId'])
        if key in seen:raise ValueError('Duplicate actual serve ID')
        seen.add(key)
        if r.get('eventType') not in ('serve','let'):
            raise ValueError('Only actual serve contacts can receive speed overlays')
        if r.get('contactVerified') is not True:
            raise ValueError('Agent must verify outgoing contact evidence before placement')
        if r.get('serveNumber') not in (1,2):raise ValueError('Actual serve opportunity number required')
        speed=float(r['launchSpeedKphEstimate'])
        if not math.isfinite(speed) or speed<=0:raise ValueError('Invalid speed estimate')
        method=r['method']
        if method=='model_imputed' and not r.get('imputationBasis'):
            raise ValueError('Model imputation needs its own documented basis')
        c=r['clip']
        for val in (c['startFrame'],c['durationFrames'],c['sourceInUs'],r['confirmedPostContactUs']):
            if not isinstance(val,int) or isinstance(val,bool):raise ValueError('Exact integer frames and source microseconds required')
        rate=fraction(c['playbackRate'])
        if rate<=0 or c['durationFrames']<=0:raise ValueError('Forward constant-rate clip required')
        local=Fraction(r['confirmedPostContactUs']-c['sourceInUs'],1000000)*fps/rate
        if local<0 or local>=c['durationFrames']:
            raise ValueError('Verified outgoing event is not inside this retained clip')
        start=c['startFrame']+math.floor(local)+1
        caps=[start+limit,c['startFrame']+c['durationFrames']]
        for field in ('pointEndFrame','nextServeStartFrame'):
            if field in r:
                if not isinstance(r[field],int):raise ValueError('Frame cap must be integer')
                caps.append(r[field])
        end=min(caps)
        if end<=start:raise ValueError('No visible frame remains after outgoing evidence')
        label='一发' if r['serveNumber']==1 else '二发'
        states=[dict(startFrame=c['startFrame'],endFrame=end,label=label)]
        fault_after_window=False
        if 'doubleFaultConfirmedUs' in r:
            fault=r['doubleFaultConfirmedUs']
            if r['eventType']!='serve' or r['serveNumber']!=2 or type(fault) is not int or fault<r['confirmedPostContactUs']:
                raise ValueError('Double fault needs a second serve and later verified fault evidence')
            fault_frame=c['startFrame']+math.floor(Fraction(fault-c['sourceInUs'],1000000)*fps/rate)+1
            if fault_frame<end:
                states[0]['endFrame']=fault_frame
                states.append(dict(startFrame=fault_frame,endFrame=end,label='二发 · 双误'))
            else:fault_after_window=True
        out.append(dict(setNumber=r['setNumber'],pointId=r['pointId'],serveId=r['serveId'],startFrame=start,endFrame=end,durationFrames=end-start,
                        labelStartFrame=c['startFrame'],labelEndFrame=end,labelStates=states,outcomeAfterOverlayWindow=fault_after_window,
                        qualifier='补估' if method=='model_imputed' else '约',speed=str(math.floor(speed+.5)),unit='km/h',statsIncluded=r['statsIncluded']))
    return out

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('input');p.add_argument('output');a=p.parse_args()
    d=json.loads(Path(a.input).read_text(encoding='utf-8-sig'))
    Path(a.output).write_text(json.dumps(build_plan(d['records'],d['fps']),ensure_ascii=False,indent=2),encoding='utf8')

